    // Créer un tableau pour stocker les positions de cette particule
    cheminsParParticule[this.id] = {
      points: []
    };
  }

  update(poidsPerlin, poidsAttraction, vitesseMax) {

		const tmpTarget = createVector(this.targetX, this.targetY)
		//const tmpTarget = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))

		this.vie -= 1 * random(0.8, 2);

    // Vérifier si la particule est morte (arrivée au centre)
    this.distanceTarget = dist(this.x, this.y, tmpTarget.x, tmpTarget.y);

    if (this.distanceTarget < rayonTarget) {
       this.vie -= attenuationCentre;
    }

    if (this.vie < 0) {
      this.morte = true;
      return;
    }

    this.couleur = 255;

    // Calculer la direction vers le centre
    const dirX = tmpTarget.x - this.x;
    const dirY = tmpTarget.y - this.y;
    const longueur = sqrt(dirX * dirX + dirY * dirY);

    // Normaliser et appliquer l'attraction vers le centre
    const forceX = (dirX / longueur) * attractionTarget;
    const forceY = (dirY / longueur) * attractionTarget;

    // Calculer la force du bruit de Perlin
    const angleP = noise(this.x * noiseScale, this.y * noiseScale) * TWO_PI * 2;
    const forcePerlinX = cos(angleP) * 0.1;
    const forcePerlinY = sin(angleP) * 0.1;

    // Mettre à jour la vitesse avec une moyenne pondérée
    this.vx += (forcePerlinX * poidsPerlin) + (forceX * poidsAttraction);
    this.vy += (forcePerlinY * poidsPerlin) + (forceY * poidsAttraction);

    // Limiter la vitesse
    const vitesse = sqrt(this.vx * this.vx + this.vy * this.vy);
    if (vitesse > vitesseMax) {
      this.vx = (this.vx / vitesse) * vitesseMax;
      this.vy = (this.vy / vitesse) * vitesseMax;
    }

    // Mettre à jour la position
	  this.px = this.x; 
	  this.py = this.y;
    this.x += this.vx;
    this.y += this.vy;
  }

  afficher() {

    //const taille = map(this.vie, 0, lifeParticule, 0.01, 1);
    //ellipse(this.x, this.y, taille, taille);
    line(this.px, this.py, this.x, this.y)
    // Stocker la position actuelle dans le tableau global
    cheminsParParticule[this.id].points.push({
      x: this.x,
      y: this.y
    });
  }

  estMorte() {
    return this.morte;
  }
}

